from itertools import product

reps = ["Kim", "Mahr", "Parra", "Quinn", "Stuckey", "Tiao", "Udall"]

def valid(a):
    # Exactly one of Parra/Tiao in Zone 1
    if (a["Parra"] == 1) == (a["Tiao"] == 1):
        return False
    # Exactly one of Tiao/Udall in Zone 2
    if (a["Tiao"] == 2) == (a["Udall"] == 2):
        return False
    if a["Parra"] != a["Quinn"]:
        return False
    if a["Stuckey"] != a["Udall"]:
        return False
    counts = {z: sum(1 for r in reps if a[r] == z) for z in (1, 2, 3)}
    return counts[3] > counts[2]

